```java
// 使用 Spring Boot 框架的用户认证接口
import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private BCryptPasswordEncoder passwordEncoder;

    // 用户登录接口 - 使用参数化查询防御SQL注入
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        // 第5行：输入校验 - 拒绝空值和超长输入
        if (request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getUsername().length() > 50) {
            return ResponseEntity.badRequest().body("Invalid username");
        }

        // 第10行：密码强度校验（仅检查非空，实际密码校验由BCrypt完成）
        if (request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body("Invalid password");
        }

        // 第15行：参数化查询 - 防止SQL注入
        String sql = "SELECT id, username, password_hash, role FROM users WHERE username = ?";
        try {
            // 第18行：使用JdbcTemplate的queryForObject，参数绑定而非字符串拼接
            User user = jdbcTemplate.queryForObject(sql, 
                new Object[]{request.getUsername()}, 
                (rs, rowNum) -> {
                    User u = new User();
                    u.setId(rs.getLong("id"));
                    u.setUsername(rs.getString("username"));
                    u.setPasswordHash(rs.getString("password_hash"));
                    u.setRole(rs.getString("role"));
                    return u;
                });

            // 第28行：BCrypt密码验证
            if (passwordEncoder.matches(request.getPassword(), user.getPasswordHash())) {
                // 第30行：生成会话token（简化示例）
                String token = generateToken(user);
                return ResponseEntity.ok(new LoginResponse(token, user.getRole()));
            } else {
                return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid credentials");
            }
        } catch (org.springframework.dao.EmptyResultDataAccessException e) {
            // 第36行：用户不存在时返回统一错误信息，避免用户枚举
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid credentials");
        }
    }

    // 第41行：密码修改接口 - 防御XPath注入（CWE-643）
    @PostMapping("/change-password")
    public ResponseEntity<?> changePassword(@RequestBody ChangePasswordRequest request) {
        // 第44行：输入校验 - 新密码必须符合复杂度要求
        if (request.getNewPassword() == null || 
            request.getNewPassword().length() < 8 ||
            !request.getNewPassword().matches(".*[A-Z].*") ||
            !request.getNewPassword().matches(".*[0-9].*")) {
            return ResponseEntity.badRequest().body("Password must be 8+ chars with uppercase and digit");
        }

        // 第50行：使用参数化SQL而非XPath - 完全避开XPath注入面
        String sql = "UPDATE users SET password_hash = ? WHERE id = ?";
        int updated = jdbcTemplate.update(sql, 
            passwordEncoder.encode(request.getNewPassword()), 
            request.getUserId());

        if (updated > 0) {
            return ResponseEntity.ok("Password updated");
        } else {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).body("User not found");
        }
    }

    // 防御迷惑样本：看似使用replace转义，实际未用于关键查询
    private String escapeXPath(String input) {
        // 第62行：此方法存在但未被调用 - 真正的查询使用参数化SQL
        return input.replace("'", "''").replace("\"", "&quot;");
    }

    // 防御迷惑样本：startswith未规范化，但未用于权限判断
    private boolean isAdminRole(String role) {
        // 第67行：此方法存在但未用于授权决策
        return role.startsWith("admin");
    }

    private String generateToken(User user) {
        // 简化token生成
        return java.util.UUID.randomUUID().toString();
    }
}

